/* Visible catalogue. Products flagged `hidden` (no real photo yet) are kept in the data
   but filtered out of EVERYTHING that renders from PRODUCTS — shop, home, build-a-box,
   quiz and product pages. To re-enable one, just drop its `hidden` flag once a photo lands. */
const PRODUCTS = ALL_PRODUCTS.filter(p => !p.hidden);

/* Image resolver — change EXT to 'png'/'jpg' (or per-SKU map) when real photos land.
   Files live in assets/products/<SKU>-fop.<ext> (front of pack) and -pack.<ext> (multipack). */
const IMG_EXT = 'svg'; // fallback for products without real photos yet
// Real product photography. Where only one shot exists, it's used for both
// the front-of-pack and the multipack (hover) slot until the other lands.
// Product images embedded as data URIs so they load with the page code
// (robust on file:// / Google Drive). Swap back to file paths for Shopify.
const IMG_OVERRIDES = {
  FUN1001: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1003: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1007: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1014: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1019: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1021: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1026: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1027: { front: 'data:image/jpeg;base64,', pack: 'data:image/jpeg;base64,' },
  FUN1002: { front: 'data:image/svg+xml;base64,', pack: 'data:image/svg+xml;base64,' },
  FUN1005: { front: 'data:image/svg+xml;base64,', pack: 'data:image/svg+xml;base64,' },
  FUN1006: { front: 'data:image/svg+xml;base64,', pack: 'data:image/svg+xml;base64,' },
  FUN1008: { front: 'data:image/svg+xml;base64,', pack: 'data:image/svg+xml;base64,' }
};
function productImg(skuOrProduct, which = 'front') {
  const sku = typeof skuOrProduct === 'string' ? skuOrProduct : skuOrProduct.sku;
  if (IMG_OVERRIDES[sku] && IMG_OVERRIDES[sku][which]) return IMG_OVERRIDES[sku][which];
  return `assets/products/${sku}-${which === 'pack' ? 'pack' : 'fop'}.${IMG_EXT}`;
}

/* Helpers */
function getProduct(sku) { return PRODUCTS.find(p => p.sku === sku); }
function mixableProducts() { return PRODUCTS.filter(p => p.mixable); }
function money(v) { return STORE.currency + Number(v).toLocaleString('en-ZA', { minimumFractionDigits: 0, maximumFractionDigits: 0 }); }

/* Expose globally (no modules — keeps it Shopify-portable & build-free) */
window.STORE = STORE;
window.PILLARS = PILLARS;
window.PRODUCTS = PRODUCTS;
window.getProduct = getProduct;
window.mixableProducts = mixableProducts;
window.money = money;
window.productImg = productImg;
